/**
 * FULL FLEX – Commercial Offering Migration Dashboard (Appsmith Custom Widget)
 * Vanilla JS (no build step) so the committed srcDoc runs as-is.
 *
 * Data contract:  appsmith.model.accounts = array of Account rows from the
 * `AccountMigration` SOQL query (account grain, active-contract accounts).
 * Expected fields per row:
 *   Name, GTM_Motion_Account__c, Account_Owner_s_Manager__c (TL),
 *   Account_Owner__c (IC), New_Commercial_Offering__c (bool),
 *   Opportunities: { records: [{ Hire_2_0__c: bool }] }  (active-contract opps)
 */

var SEGMENTS = [
  { key: "migrated",    label: "Migriert",     color: "#1f9d55" },
  { key: "inMigration", label: "In Migration", color: "#e0a800" },
  { key: "open",        label: "Noch offen",   color: "#8a94a6" }
];
var SEG_BY_KEY = {};
SEGMENTS.forEach(function (s) { SEG_BY_KEY[s.key] = s; });

var state = { tab: "account", groupBy: "motion", search: "", expanded: {} };

/* ---------- data helpers ---------- */

function rawAccounts() {
  var m = (window.appsmith && appsmith.model) || {};
  var rows = m.accounts;
  if (Array.isArray(rows)) return rows;                       // SOQL plugin shape
  if (rows && Array.isArray(rows.records)) return rows.records; // Salesforce REST shape
  return [];
}

function oppList(r) {
  var o = r.Opportunities;
  if (!o) return [];
  if (Array.isArray(o)) return o;
  if (Array.isArray(o.records)) return o.records;
  return [];
}

function segmentOf(r) {
  if (r.New_Commercial_Offering__c === true) return "migrated";
  var pot = oppList(r).some(function (o) { return o && o.Hire_2_0__c === true; });
  return pot ? "inMigration" : "open";
}

var NONE_MOTION = "— ohne Motion";
var NONE_TL = "— ohne Team Lead";
var NONE_IC = "— ohne Owner";

function normalize(r) {
  return {
    name: r.Name || "(ohne Name)",
    motion: r.GTM_Motion_Account__c || NONE_MOTION,
    tl: r.Account_Owner_s_Manager__c || NONE_TL,
    ic: r.Account_Owner__c || (r.Owner && r.Owner.Name) || NONE_IC,
    segment: segmentOf(r)
  };
}

function matchesSearch(a, q) {
  if (!q) return true;
  q = q.toLowerCase();
  return (a.name + " " + a.motion + " " + a.tl + " " + a.ic).toLowerCase().indexOf(q) !== -1;
}

function emptyCounts() { return { migrated: 0, inMigration: 0, open: 0, total: 0 }; }
function addTo(c, seg) { c[seg] += 1; c.total += 1; }

/* Build nested tree by the given key path (e.g. ["motion","tl","ic"]). */
function buildTree(accounts, keys) {
  var root = { counts: emptyCounts(), children: {}, _order: [] };
  accounts.forEach(function (a) {
    addTo(root.counts, a.segment);
    var node = root;
    for (var i = 0; i < keys.length; i++) {
      var k = a[keys[i]];
      if (!node.children[k]) {
        node.children[k] = { counts: emptyCounts(), children: {}, _order: [], accounts: [], label: k };
        node._order.push(k);
      }
      node = node.children[k];
      addTo(node.counts, a.segment);
      if (i === keys.length - 1) node.accounts.push(a);
    }
  });
  return root;
}

function sortedChildren(node) {
  return node._order
    .map(function (k) { return node.children[k]; })
    .sort(function (a, b) {
      if (b.counts.total !== a.counts.total) return b.counts.total - a.counts.total;
      return String(a.label).localeCompare(String(b.label));
    });
}

/* ---------- rendering ---------- */

function el(tag, cls, html) {
  var e = document.createElement(tag);
  if (cls) e.className = cls;
  if (html != null) e.innerHTML = html;
  return e;
}

function esc(s) {
  return String(s).replace(/[&<>"]/g, function (c) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
  });
}

function pct(n, d) { return d ? Math.round((n / d) * 100) : 0; }

function stackedBar(counts) {
  var bar = el("div", "bar");
  SEGMENTS.forEach(function (s) {
    var w = counts.total ? (counts[s.key] / counts.total) * 100 : 0;
    if (w > 0) {
      var span = el("span");
      span.style.width = w + "%";
      span.style.background = s.color;
      span.title = s.label + ": " + counts[s.key];
      bar.appendChild(span);
    }
  });
  return bar;
}

function segLegend(counts) {
  return SEGMENTS.map(function (s) {
    return '<span style="color:' + s.color + '">●</span> ' + counts[s.key];
  }).join("&nbsp;&nbsp;");
}

function treeRow(node, level, path, hasChildren) {
  var row = el("div", "row lvl" + level + (hasChildren ? " clickable" : ""));
  var open = !!state.expanded[path];

  var nameCell = el("div", "name-cell");
  nameCell.style.paddingLeft = (level * 18) + "px";
  var caret = el("span", "caret" + (open ? " open" : ""), hasChildren ? "▶" : "");
  nameCell.appendChild(caret);
  nameCell.appendChild(el("span", "name-txt", esc(node.label)));
  row.appendChild(nameCell);

  row.appendChild(el("div", "num count-big", String(node.counts.total)));

  var barCell = el("div", "");
  var bw = el("div", "bar-wrap");
  bw.appendChild(stackedBar(node.counts));
  bw.appendChild(el("div", "bar-legend", segLegend(node.counts)));
  barCell.appendChild(bw);
  row.appendChild(barCell);

  row.appendChild(el("div", "mig-pct", pct(node.counts.migrated, node.counts.total) + "%"));

  if (hasChildren) {
    row.addEventListener("click", function () {
      state.expanded[path] = !state.expanded[path];
      render();
    });
  }
  return row;
}

function renderNode(container, node, level, path, isLeafLevel) {
  var children = sortedChildren(node);
  children.forEach(function (child) {
    var childPath = path + "/" + child.label;
    var hasChildren = isLeafLevel ? child.accounts.length > 0 : child._order.length > 0;
    container.appendChild(treeRow(child, level, childPath, hasChildren));
    if (state.expanded[childPath]) {
      if (isLeafLevel) {
        // leaf: list individual accounts with a segment badge
        child.accounts
          .slice()
          .sort(function (a, b) { return a.name.localeCompare(b.name); })
          .forEach(function (a) {
            var seg = SEG_BY_KEY[a.segment];
            var acct = el("div", "acct");
            acct.style.paddingLeft = ((level + 1) * 18 + 26) + "px";
            var badge = el("span", "badge", seg.label);
            badge.style.background = seg.color;
            acct.appendChild(badge);
            acct.appendChild(el("span", "name-txt", esc(a.name)));
            container.appendChild(acct);
          });
      } else {
        renderNode(container, child, level + 1, childPath, level + 1 === (state.groupBy === "motion" ? 2 : 1));
      }
    }
  });
}

function kpiCard(labelHtml, value, sub, cls) {
  var c = el("div", "kpi" + (cls ? " " + cls : ""));
  c.appendChild(el("div", "k-label", labelHtml));
  c.appendChild(el("div", "k-value", value));
  if (sub) c.appendChild(el("div", "k-sub", sub));
  return c;
}

function renderAccountView(container, accounts) {
  var total = accounts.length;
  var counts = emptyCounts();
  accounts.forEach(function (a) { addTo(counts, a.segment); });

  // KPI row
  var kpis = el("div", "kpis");
  kpis.appendChild(kpiCard("Accounts (aktiver Vertrag)", String(total),
    pct(counts.migrated, total) + "% migriert", "total"));
  SEGMENTS.forEach(function (s) {
    var label = '<span class="dot" style="background:' + s.color + '"></span>' + s.label;
    kpis.appendChild(kpiCard(label, String(counts[s.key]), pct(counts[s.key], total) + "% aller Accounts"));
  });
  container.appendChild(kpis);

  // Controls
  var controls = el("div", "controls");
  var toggle = el("div", "seg-toggle");
  [["motion", "Nach Motion"], ["tl", "Nach Team Lead"]].forEach(function (t) {
    var b = el("button", state.groupBy === t[0] ? "active" : "", t[1]);
    b.addEventListener("click", function () {
      if (state.groupBy !== t[0]) { state.groupBy = t[0]; state.expanded = {}; render(); }
    });
    toggle.appendChild(b);
  });
  controls.appendChild(toggle);

  var search = el("div", "search");
  search.appendChild(el("span", "ico", "🔍"));
  var input = el("input");
  input.type = "text";
  input.placeholder = "Account, IC, TL oder Motion suchen…";
  input.value = state.search;
  input.addEventListener("input", function (e) {
    state.search = e.target.value;
    rerenderBody();
  });
  search.appendChild(input);
  controls.appendChild(search);
  container.appendChild(controls);

  // Body (filterable without losing focus)
  var body = el("div");
  body.id = "av-body";
  container.appendChild(body);
  renderAccountBody(body, accounts);
}

function renderAccountBody(body, accounts) {
  body.innerHTML = "";
  var filtered = accounts.filter(function (a) { return matchesSearch(a, state.search); });

  var keys = state.groupBy === "motion" ? ["motion", "tl", "ic"] : ["tl", "ic"];
  var leafLevel = keys.length - 1;
  var tree = buildTree(filtered, keys);

  var treeEl = el("div", "tree");
  var head = el("div", "thead");
  head.appendChild(el("div", "", state.groupBy === "motion" ? "Motion / Team Lead / IC" : "Team Lead / IC"));
  head.appendChild(el("div", "num", "Accounts"));
  head.appendChild(el("div", "", "Verteilung"));
  head.appendChild(el("div", "num", "Migr. %"));
  treeEl.appendChild(head);

  if (filtered.length === 0) {
    treeEl.appendChild(el("div", "row", '<div style="grid-column:1/-1;color:#8a94a6;padding:14px 0;text-align:center">Keine Treffer für „' + esc(state.search) + "”</div>"));
  } else {
    renderNode(treeEl, tree, 0, "root", 0 === leafLevel);
  }
  body.appendChild(treeEl);
}

function rerenderBody() {
  var body = document.getElementById("av-body");
  if (body) renderAccountBody(body, currentAccounts());
}

function renderOpportunityView(container) {
  var p = el("div", "placeholder");
  p.innerHTML =
    '<div class="pill">Als Nächstes</div>' +
    "<h3>Opportunity View</h3>" +
    '<p style="max-width:520px;margin:0 auto;line-height:1.7">' +
    "Detailsicht auf Opportunity-Ebene: aktive Verträge nach <b>Contract End Date</b>, " +
    "<b>Migration Potential</b> je Opportunity, Contract-Typ und Timeline der auslaufenden Verträge — " +
    "als Basis für die Migrations-Priorisierung pro IC." +
    "</p>";
  container.appendChild(p);
}

function currentAccounts() {
  return rawAccounts().map(normalize);
}

function render() {
  var root = document.getElementById("root");
  if (!root) return;
  root.innerHTML = "";

  var app = el("div", "app");

  var header = el("div", "header");
  header.appendChild(el("h1", "", "FULL FLEX · Commercial Offering Migration"));
  header.appendChild(el("div", "sub", "Accounts mit aktivem Vertrag (Contract End Date in der Zukunft), segmentiert nach Migrationsstatus"));
  app.appendChild(header);

  var tabs = el("div", "tabs");
  [["account", "Account View"], ["opportunity", "Opportunity View"]].forEach(function (t) {
    var tab = el("div", "tab" + (state.tab === t[0] ? " active" : ""), t[1]);
    tab.addEventListener("click", function () { state.tab = t[0]; render(); });
    tabs.appendChild(tab);
  });
  app.appendChild(tabs);

  var accounts = currentAccounts();

  if (state.tab === "opportunity") {
    renderOpportunityView(app);
  } else if (accounts.length === 0) {
    var empty = el("div", "empty");
    empty.innerHTML =
      "<h3>Noch keine Daten verbunden</h3>" +
      "<p>Dieses Widget erwartet die Salesforce-Query <code>AccountMigration</code> " +
      "(REST-Datenquelle) über <code>appsmith.model.accounts</code>.</p>" +
      "<ol>" +
      "<li>Query <code>AccountMigration</code> · Command <b>Custom Action</b> · Method <b>GET</b> · " +
      "Path <code>/services/data/v67.0/query</code> · Param <code>q</code> = die SOQL.</li>" +
      "<li>Widget-Property <b>Default Model</b>: <code>{{ { accounts: AccountMigration.data } }}</code></li>" +
      "<li>Query beim Laden der Seite ausführen (Run on page load).</li>" +
      "</ol>";
    app.appendChild(empty);
  } else {
    renderAccountView(app, accounts);
  }

  root.appendChild(app);
}

/* ---------- boot ---------- */
if (window.appsmith && appsmith.onReady) {
  appsmith.onReady(function () { render(); });
  if (appsmith.onModelChange) appsmith.onModelChange(function () { render(); });
} else {
  render();
}
